mapper.select:
select f.fundacct, c.custno, c.invnm, c.invtp, c.idtp, c.idno, te.brokername, te.brokeridtp, te.brokeridno from tradeaccoinfo t, tradeaccoinfoex te, custinfo c, fundaccoinfo f where f.custno = t.custno and t.tradeacco = te.tradeacco
and c.custno = t.custno and t.tradeacco = #{tradeacco}
and c.custno = f.custno and f.fundacct = #{fundacct}

		SELECT 
			   F.SERIALNO		serialno,		
		       F.CUSTNO			custno,
		       F.FUNDACCT		fundacco,
		       F.TRADEACCO		tradeacco,
		       F.APKIND			dsapkind,
           	   (SELECT PMNM FROM PARAMETER T1 WHERE T1.PMST = 'SYSTEM' AND T1.PMKY = 'APKIND' AND T1.PMV2 = 'T' AND T1.PMCO = F.APKIND) dsapkindnm,
		       C.INVNM			invnm,
		       F.BANKACCO		bankacco,
		       F.CHKFLAG		chkflag,
		       (SELECT PMNM FROM PARAMETER T1 WHERE T1.PMST = 'DS' AND T1.PMKY = 'CHKFLAG' AND T1.PMCO = F.CHKFLAG) chkflagnm,
		       F.FUNDID			fundid,
		       (SELECT T.FUNDNM FROM FUNDINFO T WHERE T.FUNDID = F.FUNDID) fundnm,
		       TO_CHAR(F.SUBAMT,'FM9,999,999,999,999,990.00') subamt,
           	   TO_CHAR(F.SUBQUTY,'FM9,999,999,999,999,990.00') subquty,
		       TO_CHAR(TO_DATE(F.WORKDATE,'YYYY-MM-DD'),'YYYY-MM-DD')		workdate,
		       F.APPLYST		applyst,
		       (SELECT PMNM FROM PARAMETER T1 WHERE T1.PMST = 'DS' AND T1.PMKY = 'CHKFLAG' AND T1.PMCO = F.APPLYST) applystnm,
		       F.OPID			operatorId,
		       F.APPNO			appno
		  FROM APPTRADEBLOTTER F, CUSTINFO C
		 WHERE C.CUSTNO = F.CUSTNO
		   AND F.ACCPTMD != '2'

		   AND F.TRADEACCO = #{sp.tradeacco}


		   AND F.FUNDACCT = #{sp.fundacco}


		   AND F.SERIALNO = #{sp.serialno}


		   AND F.APKIND = #{sp.dsapkind}


		   AND F.CHKFLAG = #{sp.checkst}


		   AND F.WORKDATE BETWEEN #{sp.begindate} AND #{sp.enddate}


		   AND F.MANAGERNO = #{sp.checkno}


		   AND F.ACCPTMD = #{sp.trustType}


		   AND F.FUNDID = #{sp.fundid}


		   AND F.OPID = #{sp.operatorId}


		   AND F.OPID != #{sp.batchoperatorId}


		   AND F.OPID != #{sp.batchoperatorId}


		   AND F.CHKFLAG in ('N','R') and F.APPLYST != 'F'


		   AND F.CHKFLAG = #{sp.checkst}


		   AND F.OPID = #{sp.batchoperatorId}

		 ORDER BY DECODE(F.CHKFLAG,'N',1,'R',2,'C',3,'Y',4), F.INSERTTIMESTAMP

SELECT SUM(DECODE(F.CHKFLAG, 'N', 1, 0)) AS ncount, SUM(DECODE(F.CHKFLAG || F.APPLYST, 'YN', 1, 0) + DECODE(F.CHKFLAG || F.APPLYST, 'YK', 1, 0)) AS ycount, SUM(DECODE(F.CHKFLAG, 'C', 1, 0)) AS fcount, SUM(DECODE(F.CHKFLAG || F.APPLYST, 'RF', 1, 0)) AS rfcount, (SUM(DECODE(F.CHKFLAG, 'R', 1, 0)) - SUM(DECODE(F.CHKFLAG || F.APPLYST, 'RF', 1, 0))) AS rccount, SUM(DECODE(F.CHKFLAG, 'R', 1, 0)) AS ccount, SUM(DECODE(F.CHKFLAG || F.APPLYST, 'YC', 1, 0)) AS cancelcount FROM APPTRADEBLOTTER F, CUSTINFO C WHERE F.CUSTNO = C.CUSTNO AND F.ACCPTMD != '2' AND F.REGIONCODE = '0001' AND F.WORKDATE = (SELECT RTRIM(KYDATE) FROM SYSALTER WHERE KEY1 = 'EC' AND KEY2 = 'SYS' AND KEY3 = 'WORKDATE')
AND F.OPID = #{sp.batchoperatorId}
AND F.FUNDID = #{sp.fundid}

SELECT F.APKIND dsapkind, (SELECT PMNM FROM PARAMETER T1 WHERE T1.PMST = 'SYSTEM' AND T1.PMKY = 'APKIND' AND T1.PMV2 = 'T' AND T1.PMCO = F.APKIND) dsapkindnm, F.FUNDID fundid, (SELECT T.FUNDNM FROM FUNDINFO T WHERE T.FUNDID = F.FUNDID) fundnm, TO_CHAR(SUM(F.SUBAMT),'FM9,999,999,999,999,990.00') sumsubamt, TO_CHAR(TO_DATE(F.WORKDATE,'YYYY-MM-DD'),'YYYY-MM-DD') workdate, TO_CHAR(SUM(F.SUBQUTY),'FM9,999,999,999,999,990.00') sumsubquty, F.OPID operatorId, COUNT(*) totalRow, (SELECT COUNT(*) FROM APPTRADEBLOTTER A, CUSTINFO B WHERE A.CUSTNO = B.CUSTNO AND F.OPID = A.OPID AND F.APKIND = A.APKIND AND A.ACCPTMD != '2' AND A.FUNDID = F.FUNDID AND A.WORKDATE = F.WORKDATE AND A.CHKFLAG IN ('N', 'R') AND A.APPLYST != 'F') nopcount FROM APPTRADEBLOTTER F, CUSTINFO C WHERE C.CUSTNO = F.CUSTNO AND F.ACCPTMD != '2'
AND F.FUNDID = #{sp.fundid}
AND F.OPID = #{sp.operatorId}
AND F.WORKDATE BETWEEN #{sp.begindate} AND #{sp.enddate}
AND F.APKIND = #{sp.dsapkind}
AND F.CHKFLAG in ('N','R') and F.APPLYST != 'F'
AND F.CHKFLAG = #{sp.checkst}
GROUP BY F.APKIND, F.FUNDID, F.OPID, F.WORKDATE ORDER BY MAX(F.INSERTTIMESTAMP) ASC

SELECT T1.FUNDACCT fundacco, T1.TRADEACCO tradeacco, TO_CHAR(TO_DATE(T1.WORKDATE,'YYYY-MM-DD'),'YYYY-MM-DD') workdate, T1.SERIALNO serialno, T1.APKIND dsapkind, (SELECT PMNM FROM PARAMETER T1 WHERE T1.PMST = 'SYSTEM' AND T1.PMKY = 'APKIND' AND T1.PMV2 = 'T' AND T1.PMCO = T1.APKIND) dsapkindnm, T1.FUNDID fundid, (SELECT T.FUNDNM FROM FUNDINFO T WHERE T.FUNDID = T1.FUNDID) fundnm, TO_CHAR(T1.SUBAMT,'FM9,999,999,999,999,990.00') subAmt, TO_CHAR(T1.SUBQUTY,'FM9,999,999,999,999,990.00') subQuty, T1.CUSTNO custno, C.INVNM invnm, C.IDTP idtp, (SELECT PMNM FROM PARAMETER T1 WHERE T1.PMST = 'SYSTEM' AND T1.PMKY = 'IDTP' AND T1.PMCO = C.IDTP) idtpnm, C.IDNO idno, C.INVTP invtp, (SELECT PMNM FROM PARAMETER T1 WHERE T1.PMST = 'SYSTEM' AND T1.PMKY = 'INVTP' AND T1.PMCO = C.INVTP) invtpnm, T1.BROKER broker, T1.BKIDTP contidtp, (SELECT PMNM FROM PARAMETER T1 WHERE T1.PMST = 'SYSTEM' AND T1.PMKY = 'IDTP' AND T1.PMCO = T1.BKIDTP) contidtpnm, T1.BKIDNO contidno, T1.APPLYST applyst, DECODE(T1.APPLYST, 'N', '正常', 'K', '正常', 'C', '已撤单', 'F', '已作废') applystnm, T1.OPID operatorId FROM APPTRADEBLOTTER T1, CUSTINFO C, DS_CUSTCLASSINFO DS WHERE C.CUSTNO = T1.CUSTNO AND C.CUSTNO = DS.CUSTNO(+) AND T1.CHKFLAG = 'Y' AND T1.PAYST NOT IN ('Y', 'I') AND T1.SERIALNO NOT IN (SELECT SERIALNO FROM BANK_STATEMENT_ACCOUNT WHERE SERIALNO IS NOT NULL) AND T1.ACCPTMD != '1' AND APPLYST IN ('K', 'N', 'C')
AND T1.TRADEACCO = #{sp.tradeacco}
AND T1.FUNDACCT = #{sp.fundacco}
AND ds.CUSTABBRCODE = nvl(#{sp.firstCustGroup},CUSTABBRCODE)
AND ds.CUSTINSTREPRCODE = nvl(#{sp.secondCustGroup},CUSTINSTREPRCODE)
ORDER BY SERIALNO ASC
